 metrics jsonb NOT NULL DEFAULT '{}' CHECK (jsonb_typeof(metrics)='object'),
 receipt_sha256 text NOT NULL CHECK (receipt_sha256 ~ '^[0-9a-f]{64}$'),
 receipt jsonb NOT NULL CHECK (jsonb_typeof(receipt)='object'),
