 updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 UNIQUE(run_id,attempt)
);
CREATE TRIGGER run_changes BEFORE INSERT OR UPDATE OR DELETE ON planning.runs
 FOR EACH ROW EXECUTE FUNCTION planning.record_change();

CREATE FUNCTION planning.put_run(document jsonb, fingerprint text, expected bigint)
RETURNS bigint LANGUAGE plpgsql AS $$
DECLARE prior planning.runs; answer bigint; logical_id text;
BEGIN
 logical_id := document->>'id';
 PERFORM pg_advisory_xact_lock(734801);
 SELECT * INTO prior FROM planning.runs WHERE id=logical_id FOR UPDATE;
 IF FOUND THEN
   IF prior.receipt=document AND prior.receipt_sha256=fingerprint THEN RETURN prior.revision; END IF;
   IF prior.revision<>expected THEN RAISE EXCEPTION 'stale run revision'; END IF;
   IF prior.status<>'running' THEN RAISE EXCEPTION 'terminal run is immutable'; END IF;
   IF prior.item_id IS DISTINCT FROM document->>'item_id'
     OR prior.run_id IS DISTINCT FROM document->>'run_id'
     OR prior.attempt IS DISTINCT FROM (document->>'attempt')::integer
     OR prior.inputs IS DISTINCT FROM document->'inputs'
     OR prior.recipe_ref IS DISTINCT FROM document->>'recipe_ref'
     OR prior.parent_run_id IS DISTINCT FROM document->>'parent_run_id'
     OR prior.root_run_id IS DISTINCT FROM document->>'root_run_id'
   THEN RAISE EXCEPTION 'run identity or inputs changed; use a new attempt'; END IF;
   UPDATE planning.runs SET status=document->>'status',outputs=document->'outputs',
     checks=document->'checks',metrics=coalesce(document->'metrics','{}'),
     receipt=document,receipt_sha256=fingerprint
   WHERE id=logical_id RETURNING revision INTO answer;
 ELSE
   IF expected<>0 THEN RAISE EXCEPTION 'new run requires expected revision zero'; END IF;
   INSERT INTO planning.runs(id,item_id,run_id,attempt,parent_run_id,root_run_id,status,
     recipe_ref,reported_actor,inputs,outputs,checks,metrics,receipt_sha256,receipt)
   VALUES(logical_id,document->>'item_id',document->>'run_id',(document->>'attempt')::integer,
     document->>'parent_run_id',document->>'root_run_id',document->>'status',
     document->>'recipe_ref',document->>'actor',document->'inputs',document->'outputs',
     document->'checks',coalesce(document->'metrics','{}'),fingerprint,document)
   RETURNING revision INTO answer;
 END IF;
 RETURN answer;
END;
$$;
REVOKE ALL ON FUNCTION planning.put_run(jsonb,text,bigint) FROM PUBLIC;

CREATE VIEW planning.run_edges AS
