 UNION ALL
 SELECT r.id,r.run_id,'part-of',r.parent_run_id,jsonb_build_object('resolution','not independently verified')
 FROM planning.runs r WHERE r.parent_run_id IS NOT NULL;
REVOKE ALL ON planning.runs,planning.run_edges FROM PUBLIC;
