"""Operator-private planning records. Reuses existing SSH/psql; no new credentials."""
from __future__ import annotations
import hashlib
import importlib.util
import json
from pathlib import Path

ROOT=Path(__file__).resolve().parent
_spec=importlib.util.spec_from_file_location('planning_transport',ROOT/'plan.py')
transport=importlib.util.module_from_spec(_spec);_spec.loader.exec_module(transport)


def encode(value):return json.dumps(value,sort_keys=True,ensure_ascii=False,separators=(',',':'),allow_nan=False)
def sha(data):return hashlib.sha256(data).hexdigest()
def literal(value):return "'"+str(value).replace("'","''")+"'"
def json_sql(value):return literal(encode(value))+'::jsonb'


def execute(body, *, write=False):
    begin='BEGIN;' if write else 'BEGIN READ ONLY;'
    guard="DO $$ BEGIN IF pg_is_in_recovery() THEN RAISE EXCEPTION 'known writer is standby'; END IF; END $$;" if write else ''
    role='SET LOCAL ROLE dark_owner;' if write else ''
    sql=begin+"\nSET LOCAL statement_timeout='30s'; SET LOCAL lock_timeout='3s'; SET LOCAL standard_conforming_strings=on;\n"+guard+role+'\n'+body+'\nCOMMIT;'
    raw=transport.foundation.sql(transport.foundation.MEMBERS[0],sql,database='dark',raw=True)
    marker=raw.find('{')
    if marker<0:return {'sql_completed':True}
    result,_=json.JSONDecoder().raw_decode(raw[marker:])
    return result


def validate_receipt(doc):
    for key in ('id','item_id','run_id','recipe_ref','actor'):
        if not isinstance(doc.get(key),str) or not doc[key].strip():raise ValueError('missing '+key)
    if type(doc.get('attempt')) is not int or doc['attempt']<1:raise ValueError('invalid attempt')
    if doc.get('status') not in ('running','succeeded','findings','failed','cancelled','partial'):raise ValueError('invalid status')
    for name in ('inputs','outputs','checks'):
        if not isinstance(doc.get(name),list):raise ValueError('missing '+name)
    for ref in doc['inputs']+doc['outputs']:
        if not isinstance(ref,dict) or not ref.get('uri'):raise ValueError('missing resource URI')
        if not ref.get('sha256') and not ref.get('unknown_reason'):raise ValueError('resource digest or unknown reason required')
        if ref.get('sha256') and (len(ref['sha256'])!=64 or any(c not in '0123456789abcdef' for c in ref['sha256'])):raise ValueError('invalid resource digest')
    if doc['status']=='succeeded' and any(c.get('status')!='pass' for c in doc['checks']):raise ValueError('success with nonpassing checks')
    encode(doc)


def record(doc, expected):
    validate_receipt(doc)
    fingerprint=sha(encode(doc).encode())
    return execute('SELECT json_build_object(\'revision\',planning.put_run('+json_sql(doc)+','+literal(fingerprint)+','+str(int(expected))+'));',write=True)


def import_items(rows):
    statements=[]
    for row in rows:
        if row['kind'] not in ('work','mental_model','ingestion','optimization'):raise ValueError('invalid item kind')
        fields=['id','outcome','trail','priority','priority_reason','state','acceptance','kind','metadata','adr','meadows_level','meadows_rationale','workflow']
        values=[literal(row['id']),literal(row['outcome']),str(int(row.get('trail',4))),str(int(row.get('priority',3))),
                literal(row.get('priority_reason','Owner-requested intake; not an optimized priority score')),literal(row.get('state','proposed')),
                literal(row['acceptance']),literal(row['kind']),json_sql(row.get('metadata',{})),
                json_sql(row['adr']) if row.get('adr') else 'NULL',str(row['meadows_level']) if row.get('meadows_level') else 'NULL',
                literal(row['meadows_rationale']) if row.get('meadows_rationale') else 'NULL',json_sql(row['workflow']) if row.get('workflow') else 'NULL']
        statements.append('INSERT INTO planning.items('+','.join(fields)+') VALUES('+','.join(values)+') ON CONFLICT(id) DO NOTHING;')
    execute('SELECT pg_advisory_xact_lock(734801);\n'+'\n'.join(statements),write=True)
    return len(rows)


def snapshot():
    return execute("""SELECT json_build_object('observed_at',clock_timestamp(),'recovery',pg_is_in_recovery(),
 'work',(SELECT coalesce(json_agg(p ORDER BY priority,id),'[]') FROM planning.current_plan p),
 'runs',(SELECT coalesce(json_agg(r ORDER BY updated_at DESC),'[]') FROM (SELECT * FROM planning.runs ORDER BY updated_at DESC LIMIT 40) r),
 'counts',(SELECT coalesce(json_object_agg(kind,n),'{}') FROM (SELECT kind,count(*) n FROM planning.items GROUP BY kind) c),
 'pending',(SELECT coalesce(json_agg(q ORDER BY kind,priority,id),'[]') FROM (SELECT id,outcome,kind,state,revision,metadata FROM planning.items WHERE kind IN ('ingestion','optimization') AND state<>'verified' LIMIT 200) q),
 'decisions',(SELECT coalesce(json_agg(d ORDER BY id),'[]') FROM (SELECT id,adr,meadows_level,meadows_rationale FROM planning.items WHERE adr IS NOT NULL) d),
 'models',(SELECT coalesce(json_agg(m ORDER BY id),'[]') FROM (SELECT id,outcome,state,metadata FROM planning.items WHERE kind='mental_model') m),
 'edges',(SELECT count(*) FROM planning.run_edges),
 'auth_access',has_schema_privilege('dark_auth','planning','USAGE'));""")
